import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    if 'island' in df.columns:
        df['island'] = df['island'].replace({'Dram': 'Dream', 'Torgerson': 'Torgersen'})
    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype('string').str.strip().str.lower()
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(
            df['body_mass_g'].astype('string').str.replace(',', '', regex=False),
            errors='coerce'
        )
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    return df

def answer(df):
    df = clean(df)
    means = df.groupby('species', sort=True)['flipper_length_mm'].mean()
    return {str(k): float(v) for k, v in means.items() if pd.notna(k)}
